import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import './home.css';
import { FaHandPointUp } from "react-icons/fa";
import image from '../assest/URL QR Code.jpeg'
import imf from "../assest/lg.jpeg"

export default function Home() {
    const navigate = useNavigate();
    const [showScanner, setShowScanner] = useState(false);
    const videoRef = useRef(null);

    const handleQRClick = () => {
        navigate('/FeedbackSurvey');
    };

    useEffect(() => {
        if (showScanner && videoRef.current) {
            navigator.mediaDevices.getUserMedia({ video: true })
                .then(stream => {
                    videoRef.current.srcObject = stream;
                })
                .catch(err => {
                    console.error("Camera access denied:", err);
                    alert("Camera access needed for QR scanning");
                    setShowScanner(false);
                });
        }
    }, [showScanner]);

    if (showScanner) {
        return (
            <div className="scanner-container">
                <video ref={videoRef} autoPlay style={{ width: '100%', height: '300px' }} />
                <button onClick={() => setShowScanner(false)}>Close Scanner</button>
                <button onClick={() => navigate('/FeedbackSurvey')}>Go to About</button>
            </div>
        );
    }

    return (
        <div className="feedback-container">
            <div className="feedback-card">
                <div className="card-body">
                    <div className="logo-section">
                        <img
                            style={{height:"190px", width:"205px",paddingTop:"5px"}}
                            src={imf}
                            alt="Xpress Inn Logo"
                        />
                        <h5 className="hotel-nam">American Star Inn - Munday</h5>

                    </div>

                    <h4 className="main-text">
                        Please Leave a Quick<br />
                        Feedback or Review
                    </h4>

                    <div className="review-icons">
                        <div className="review-icon tripadvisor-icon">
                            <img
                                style={{ height: "50px", width: "50px" }}
                                src="https://cdn-icons-png.freepik.com/512/6124/6124989.png"
                                alt="TripAdvisor"
                            />
                        </div>

                        <div className="review-icon google-icon">
                            <svg width="24" height="24" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                                <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4" />
                                <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
                                <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05" />
                                <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
                            </svg>
                        </div>
                    </div>

                    <div className="qr-section" onClick={handleQRClick} style={{ cursor: 'pointer' }}>
                        <div className="qr-code">
                            <img
                                src={image}
                                alt="QR Code for Reviews"
                                className="qr-image"
                            />
                        </div>
                        <FaHandPointUp />
                        <div className="qr-text">
                            Scan me on your phone
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
